// Swap manual media to match the site's colour scheme.
//
// Every screenshot and clip is captured twice on ncSender: dark (the file as
// referenced in the page) and light (same name with a "-light" suffix before
// the extension). assets/js/theme-media.json lists which files have a light
// twin; it is generated by the capture tooling, so pages never reference the
// light file directly.
(function () {
  var MANIFEST_URL = null;
  var light = null;     // Set of "assets/images/..." paths that have a -light twin

  function manifestUrl() {
    if (MANIFEST_URL) return MANIFEST_URL;
    var s = document.querySelector('script[src*="theme-media.js"]');
    MANIFEST_URL = s ? s.getAttribute('src').replace(/theme-media\.js.*$/, 'theme-media.json') : 'assets/js/theme-media.json';
    return MANIFEST_URL;
  }

  function isDark() {
    return document.body.getAttribute('data-md-color-scheme') === 'slate';
  }

  // "…/assets/images/features/x.mp4" -> "assets/images/features/x.mp4"
  function key(url) {
    var m = /assets\/images\/.+$/.exec(url.split('?')[0]);
    return m ? m[0] : null;
  }
  // clips keep their poster next to them: x.mp4 / x-poster.jpg, and the light
  // twins are x-light.mp4 / x-light-poster.jpg
  function lightUrl(url) {
    return url.replace(/(-poster)?(\.[a-z0-9]+)$/i, '-light$1$2');
  }
  function darkUrl(url) {
    return url.replace(/-light(-poster)?(\.[a-z0-9]+)$/i, '$1$2');
  }

  function swapAttr(el, attr) {
    var url = el.getAttribute(attr);
    if (!url) return;
    var base = darkUrl(url);
    var k = key(base);
    if (!k || !light.has(k)) return;
    var want = isDark() ? base : lightUrl(base);
    if (want !== url) el.setAttribute(attr, want);
  }

  function apply() {
    if (!light) return;
    document.querySelectorAll('img[src*="assets/images/"]').forEach(function (img) { swapAttr(img, 'src'); });
    document.querySelectorAll('video').forEach(function (v) {
      var changed = false;
      var poster = v.getAttribute('poster');
      if (poster) { swapAttr(v, 'poster'); }
      v.querySelectorAll('source').forEach(function (s) {
        var before = s.getAttribute('src');
        swapAttr(s, 'src');
        if (s.getAttribute('src') !== before) changed = true;
      });
      if (changed) {
        var t = v.currentTime;
        v.load();
        v.currentTime = t || 0;
        var p = v.play(); if (p && p.catch) p.catch(function () {});
      }
    });
  }

  function load() {
    if (light) { apply(); return; }
    fetch(manifestUrl()).then(function (r) { return r.ok ? r.json() : []; }).then(function (list) {
      light = new Set(list);
      apply();
    }).catch(function () { light = new Set(); });
  }

  new MutationObserver(function (muts) {
    for (var i = 0; i < muts.length; i++) {
      if (muts[i].attributeName === 'data-md-color-scheme') { apply(); break; }
    }
  }).observe(document.body, { attributes: true });

  // Material's instant navigation re-renders the page without a full load.
  if (window.document$ && window.document$.subscribe) {
    window.document$.subscribe(load);
  } else {
    load();
  }
})();
